public class Solution {
    static class Student {
        private String name;
        private int[] scores;

        public Student(String name, int[] scores) {
            this.name = name;
            this.scores = scores.clone();
        }

        // Copy constructor with deep cloning
        public Student(Student other) {
            this.name = other.name;
            this.scores = other.scores.clone();
        }

        public void setScore(int index, int val) {
            scores[index] = val;
        }

        public void printInfo() {
            System.out.println(name + " scores: " + Arrays.toString(scores));
        }
    }

    public static void main(String[] args) {
        int[] initialScores = {85, 90, 95};
        Student original = new Student("Akshat", initialScores);
        Student copy = new Student(original);

        copy.setScore(0, 100); // Modifying copy

        System.out.print("Original: ");
        original.printInfo();
        System.out.print("Copy:     ");
        copy.printInfo();
    }
}

