public class Solution {
    static class ManagedResource {
        private boolean resourceAllocated = false;

        public ManagedResource(int configCode) {
            // Step 1: Allocate resource
            this.resourceAllocated = true;
            System.out.println("Resource allocated successfully.");

            // Step 2: Risky secondary initialization
            try {
                if (configCode < 0) {
                    throw new IllegalArgumentException("Invalid configuration code: " + configCode);
                }
            } catch (Exception e) {
                // Cleanup partially allocated resource before propagating failure
                close();
                throw e;
            }
        }

        public void close() {
            if (resourceAllocated) {
                resourceAllocated = false;
                System.out.println("Resource cleaned up safely after constructor failure.");
            }
        }
    }

    public static void main(String[] args) {
        try {
            new ManagedResource(-1);
        } catch (Exception e) {
            System.out.println("Caught in main: " + e.getMessage());
        }
    }
}

