public class Solution {
    static class Parent {
        public Parent() {
            System.out.println("Parent constructor executing");
            init(); // ANTI-PATTERN: Calling overridable method from constructor
        }

        public void init() {
            System.out.println("Parent init");
        }
    }

    static class Child extends Parent {
        private String subState = "INITIALIZED_STATE";

        public Child() {
            super();
            System.out.println("Child constructor finished. State: " + subState);
        }

        @Override
        public void init() {
            // At this point, Child field initializers have NOT run yet!
            System.out.println("Child init invoked! subState is: " + subState);
        }
    }

    public static void main(String[] args) {
        new Child();
    }
}

