    }
}

public class Solution {
    static class SafeConfig {
        private String host;
        private int port;
        private boolean ssl;

        // Constructor 1 delegates to 2
        public SafeConfig() {
            this("localhost");
        }

        // Constructor 2 delegates to 3 (master)
        public SafeConfig(String host) {
            this(host, 8080);
        }

        // Constructor 3 delegates to 4 (terminal master)
        public SafeConfig(String host, int port) {
            this(host, port, false);
        }

        // Master terminal constructor: performs actual initialization without this(...)
        public SafeConfig(String host, int port, boolean ssl) {
            this.host = host;
            this.port = port;
            this.ssl = ssl;
        }

        public void printConfig() {
            System.out.println("Config: " + host + ":" + port + " (SSL=" + ssl + ")");
        }
    }

    public static void main(String[] args) {
        SafeConfig cfg = new SafeConfig();
        cfg.printConfig();
    }
}

