import java.lang.reflect.Constructor;

public class Solution {
    static class SecureSingleton {
        private static final SecureSingleton INSTANCE = new SecureSingleton();
        private static boolean instanceCreated = false;

        private SecureSingleton() {
            synchronized (SecureSingleton.class) {
                if (instanceCreated) {
                    throw new IllegalStateException("Reflective instantiation prohibited: singleton already exists");
                }
                instanceCreated = true;
            }
        }

        public static SecureSingleton getInstance() {
            return INSTANCE;
        }
    }

    public static void main(String[] args) {
        SecureSingleton first = SecureSingleton.getInstance();
        System.out.println("Standard singleton instance acquired: " + (first != null));

        try {
            Constructor<SecureSingleton> constructor = SecureSingleton.class.getDeclaredConstructor();
            constructor.setAccessible(true);
            constructor.newInstance(); // Attempt reflective breach
        } catch (Exception e) {
            System.out.println("Security gate triggered: " + e.getCause().getMessage());
        }
    }
}
